class QueueStack {
  // Only push (add to back) and shift (take from front) are used on these arrays.
  private main: number[] = [];
  private helper: number[] = [];
  private last = 0;

  push(x: number): void {
    this.main.push(x);
    this.last = x;
  }

  pop(): number {
    while (this.main.length > 1) {
      this.last = this.main.shift()!;
      this.helper.push(this.last);
    }
    const x = this.main.shift()!;
    [this.main, this.helper] = [this.helper, this.main];
    return x;
  }

  top(): number {
    return this.last;
  }

  empty(): boolean {
    return this.main.length === 0;
  }
}

